import random, sys
sys.path.insert(0,'/workspace/project')
from modules import byte_program as bp
from modules.capture_audit import parse_requests, Budget, BudgetError

def build_node(data, rnd, depth=0):
    if len(data) == 0:
        return bp.literal(b'')
    style = rnd.random()
    if len(data) < 3 or style < 0.35 or depth > 6:
        return bp.literal(data)
    if style < 0.55:
        k = rnd.randrange(1, len(data))
        return bp.cat((build_node(data[:k], rnd, depth+1), build_node(data[k:], rnd, depth+1)))
    if style < 0.75:
        for period in range(1, min(6, len(data))):
            if len(data) % period == 0:
                unit = data[:period]
                if unit * (len(data)//period) == data:
                    return bp.repeat(build_node(unit, rnd, depth+1), len(data)//period)
        k = rnd.randrange(1, len(data))
        return bp.cat((build_node(data[:k], rnd, depth+1), build_node(data[k:], rnd, depth+1)))
    pad = bp.literal(b'PAD' + data + b'END')
    return bp.cut(pad, 3, 3+len(data))

def norm(reqs):
    return [{k:v for k,v in r.items() if not k.endswith('_bytes')} for r in reqs]

def main(n=3000):
    from diff_parse import rand_channel
    bad = 0
    for seed in range(n):
        rnd = random.Random(seed)
        data = rand_channel(rnd)
        try:
            r1, e1 = parse_requests(bp.literal(data), Budget())
        except BudgetError:
            continue
        r1 = norm(r1)
        node = build_node(data, rnd)
        assert bytes(bp.read_bytes(node,0,node.n)) == data, ('node mismatch', seed)
        assert node.h == bp.literal(data).h, ('hash mismatch', seed, data)
        assert bp.first_lf(node) == (data.find(b'\n') if data else -1), ('lf', seed)
        r2, e2 = parse_requests(node, Budget())
        r2 = norm(r2)
        if r1 != r2 or e1 != e2:
            bad += 1
            if bad < 3:
                print('MISMATCH seed', seed, data)
                print(' lit', r1, e1)
                print(' cmp', r2, e2)
    print('compressed-vs-literal parse OK, bad =', bad)

if __name__ == '__main__':
    main(int(sys.argv[1]) if len(sys.argv)>1 else 3000)
